+package org.apache.kafka.security;
+
+import org.apache.kafka.clients.admin.ScramMechanism;
+import org.apache.kafka.common.security.authenticator.CredentialCache;
+import org.apache.kafka.common.security.scram.ScramCredential;
+import org.apache.kafka.common.security.token.delegation.internals.DelegationTokenCache;
+
+import org.junit.jupiter.api.Test;
+import org.mockito.MockedConstruction;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.assertNotNull;
+import static org.junit.jupiter.api.Assertions.assertNull;
+import static org.junit.jupiter.api.Assertions.assertSame;
+import static org.mockito.Mockito.mockConstruction;
+
+public class CredentialProviderTest {
+
+    // The internal ScramMechanism drives createCache; its names match the admin enum.
+    private static final List<String> ALL_MECHANISMS = List.of("SCRAM-SHA-256", "SCRAM-SHA-512");
+
+    // A minimal ScramCredential stub (salt, storedKey, serverKey, iterations).
+    private static ScramCredential credential() {
+        return new ScramCredential(new byte[]{1}, new byte[]{2}, new byte[]{3}, 4096);
+    }
+
+    @Test
+    void testTokenCacheIsExposed() {
+        try (MockedConstruction<DelegationTokenCache> mocked =
+                 mockConstruction(DelegationTokenCache.class)) {
+            DelegationTokenCache tc = new DelegationTokenCache(ALL_MECHANISMS); // intercepted → mock #0
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, tc);
+            assertSame(mocked.constructed().get(0), provider.tokenCache);
+        }
+    }
+
+    @Test
+    void testCachesCreatedForAllRegisteredMechanisms() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            for (String mechanism : ALL_MECHANISMS) {
+                assertNotNull(
+                    provider.credentialCache.cache(mechanism, ScramCredential.class),
+                    "Expected cache for mechanism: " + mechanism
+                );
+            }
+        }
+    }
+
+    @Test
+    void testNoCacheCreatedForUnregisteredMechanism() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(List.of(), new DelegationTokenCache(ALL_MECHANISMS));
+            for (String mechanism : ALL_MECHANISMS) {
+                assertNull(
+                    provider.credentialCache.cache(mechanism, ScramCredential.class),
+                    "Expected no cache for unregistered mechanism: " + mechanism
+                );
+            }
+        }
+    }
+
+    @Test
+    void testCacheCreatedOnlyForRequestedMechanism() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(List.of("SCRAM-SHA-256"), new DelegationTokenCache(ALL_MECHANISMS));
+            assertNotNull(provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class));
+            assertNull(provider.credentialCache.cache("SCRAM-SHA-512", ScramCredential.class));
+        }
+    }
+
+    @Test
+    void testUpdateCredentialStoresInCache() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            ScramCredential cred = credential();
+
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", cred);
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class);
+            assertSame(cred, cache.get("alice"));
+        }
+    }
+
+    @Test
+    void testUpdateCredentialForSha512() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            ScramCredential cred = credential();
+
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_512, "bob", cred);
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-512", ScramCredential.class);
+            assertSame(cred, cache.get("bob"));
+        }
+    }
+
+    @Test
+    void testUpdateCredentialOverwritesExisting() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            ScramCredential first = credential();
+            ScramCredential second = credential();
+
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", first);
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", second);
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class);
+            assertSame(second, cache.get("alice"));
+        }
+    }
+
+    @Test
+    void testUpdateCredentialDoesNotAffectOtherUsers() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", credential());
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class);
+            assertNull(cache.get("bob"));
+        }
+    }
+
+    @Test
+    void testRemoveCredentialsDeletesEntry() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", credential());
+
+            provider.removeCredentials(ScramMechanism.SCRAM_SHA_256, "alice");
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class);
+            assertNull(cache.get("alice"));
+        }
+    }
+
+    @Test
+    void testRemoveCredentialsDoesNotThrowWhenUserAbsent() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            provider.removeCredentials(ScramMechanism.SCRAM_SHA_256, "nobody"); // no exception possible — cache.remove is a no-op for absent keys
+        }
+    }
+
+    @Test
+    void testRemoveCredentialsDoesNotThrowWhenCacheAbsent() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            // Cache for SCRAM-SHA-512 was never created.
+            CredentialProvider provider = new CredentialProvider(List.of("SCRAM-SHA-256"), new DelegationTokenCache(ALL_MECHANISMS));
+            // removeCredentials guards with null-check — must not throw
+            provider.removeCredentials(ScramMechanism.SCRAM_SHA_512, "alice");
+        }
+    }
+
+    @Test
+    void testRemoveCredentialsDoesNotAffectOtherUsers() {
+        try (MockedConstruction<DelegationTokenCache> ignored =
+                 mockConstruction(DelegationTokenCache.class)) {
+            CredentialProvider provider = new CredentialProvider(ALL_MECHANISMS, new DelegationTokenCache(ALL_MECHANISMS));
+            ScramCredential cred = credential();
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "alice", cred);
+            provider.updateCredential(ScramMechanism.SCRAM_SHA_256, "bob", credential());
+
+            provider.removeCredentials(ScramMechanism.SCRAM_SHA_256, "bob");
+
+            CredentialCache.Cache<ScramCredential> cache = provider.credentialCache.cache("SCRAM-SHA-256", ScramCredential.class);
+            assertSame(cred, cache.get("alice"));
+            assertNull(cache.get("bob"));
+        }
+    }
+}

