+package org.apache.kafka.security;
+
+import org.apache.kafka.common.config.types.Password;
+import org.apache.kafka.common.security.auth.KafkaPrincipal;
+import org.apache.kafka.common.security.scram.ScramCredential;
+import org.apache.kafka.common.security.scram.internals.ScramMechanism;
+import org.apache.kafka.common.security.token.delegation.DelegationToken;
+import org.apache.kafka.common.security.token.delegation.TokenInformation;
+import org.apache.kafka.common.security.token.delegation.internals.DelegationTokenCache;
+import org.apache.kafka.server.config.DelegationTokenManagerConfigs;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.mockito.MockedStatic;
+
+import java.security.InvalidKeyException;
+import java.security.NoSuchAlgorithmException;
+import java.util.Arrays;
+import java.util.Base64;
+import java.util.List;
+import java.util.Optional;
+
+import javax.crypto.Mac;
+import javax.crypto.SecretKey;
+import javax.crypto.spec.SecretKeySpec;
+
+import static org.junit.jupiter.api.Assertions.assertArrayEquals;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertNotNull;
+import static org.junit.jupiter.api.Assertions.assertNull;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+import static org.mockito.ArgumentMatchers.any;
+import static org.mockito.ArgumentMatchers.anyString;
+import static org.mockito.Mockito.doThrow;
+import static org.mockito.Mockito.mock;
+import static org.mockito.Mockito.mockStatic;
+import static org.mockito.Mockito.when;
+
+public class DelegationTokenManagerTest {
+
+    private static final String SECRET = "test-secret-key";
+    private static final KafkaPrincipal OWNER = new KafkaPrincipal(KafkaPrincipal.USER_TYPE, "alice");
+    private static final KafkaPrincipal RENEWER = new KafkaPrincipal(KafkaPrincipal.USER_TYPE, "bob");
+    private static final KafkaPrincipal STRANGER = new KafkaPrincipal(KafkaPrincipal.USER_TYPE, "charlie");
+
+    private DelegationTokenCache tokenCache;
+
+    @BeforeEach
+    void setUp() {
+        tokenCache = new DelegationTokenCache(ScramMechanism.mechanismNames());
+    }
+
+    private DelegationTokenManager managerWithSecret(String secret) {
+        DelegationTokenManagerConfigs config = mock(DelegationTokenManagerConfigs.class);
+        when(config.tokenAuthEnabled()).thenReturn(true);
+        when(config.delegationTokenSecretKey()).thenReturn(new Password(secret));
+        return new DelegationTokenManager(config, tokenCache);
+    }
+
+    private DelegationTokenManager managerWithoutSecret() {
+        DelegationTokenManagerConfigs config = mock(DelegationTokenManagerConfigs.class);
+        when(config.tokenAuthEnabled()).thenReturn(false);
+        return new DelegationTokenManager(config, tokenCache);
+    }
+
+    private TokenInformation tokenInfo(String tokenId) {
+        long now = System.currentTimeMillis();
+        return new TokenInformation(tokenId, OWNER, List.of(RENEWER), now, now + 86400000L, now + 3600000L);
+    }
+
+    @Test
+    void testIsEnabledWhenSecretKeyConfigured() {
+        assertTrue(managerWithSecret(SECRET).isEnabled());
+    }
+
+    @Test
+    void testIsDisabledWhenNoSecretKey() {
+        assertFalse(managerWithoutSecret().isEnabled());
+    }
+
+    @Test
+    void testCreateHmacIsDeterministic() {
+        SecretKey key = new SecretKeySpec(SECRET.getBytes(), "HmacSHA512");
+        byte[] hmac1 = DelegationTokenManager.createHmac("token-1", key);
+        byte[] hmac2 = DelegationTokenManager.createHmac("token-1", key);
+        assertArrayEquals(hmac1, hmac2);
+    }
+
+    @Test
+    void testCreateHmacDiffersForDifferentTokenIds() {
+        SecretKey key = new SecretKeySpec(SECRET.getBytes(), "HmacSHA512");
+        byte[] hmac1 = DelegationTokenManager.createHmac("token-1", key);
+        byte[] hmac2 = DelegationTokenManager.createHmac("token-2", key);
+        assertFalse(Arrays.equals(hmac1, hmac2));
+    }
+
+    @Test
+    void testCreateHmacDiffersForDifferentKeys() {
+        SecretKey key1 = new SecretKeySpec("key-one".getBytes(), "HmacSHA512");
+        SecretKey key2 = new SecretKeySpec("key-two".getBytes(), "HmacSHA512");
+        byte[] hmac1 = DelegationTokenManager.createHmac("token-1", key1);
+        byte[] hmac2 = DelegationTokenManager.createHmac("token-1", key2);
+        assertFalse(Arrays.equals(hmac1, hmac2));
+    }
+
+    @Test
+    void testCreateHmacProducesNonEmptyBytes() {
+        SecretKey key = new SecretKeySpec(SECRET.getBytes(), "HmacSHA512");
+        byte[] hmac = DelegationTokenManager.createHmac("token-1", key);
+        assertNotNull(hmac);
+        assertTrue(hmac.length > 0);
+    }
+
+    @Test
+    void testCreateHmacThrowsIllegalArgumentOnInvalidKey() throws Exception {
+        Mac mockMac = mock(Mac.class);
+        InvalidKeyException cause = new InvalidKeyException("bad key");
+        doThrow(cause).when(mockMac).init(any(SecretKey.class));
+
+        try (MockedStatic<Mac> macStatic = mockStatic(Mac.class)) {
+            macStatic.when(() -> Mac.getInstance(anyString())).thenReturn(mockMac);
+
+            SecretKey key = new SecretKeySpec(SECRET.getBytes(), "HmacSHA512");
+            IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
+                () -> DelegationTokenManager.createHmac("token-1", key));
+            assertInstanceOf(InvalidKeyException.class, ex.getCause());
+        }
+    }
+
+    @Test
+    void testCreateHmacThrowsRuntimeOnGeneralException() throws Exception {
+        Mac mockMac = mock(Mac.class);
+        when(mockMac.doFinal(any(byte[].class)))
+            .thenThrow(new IllegalStateException("mac not init"));
+
+        try (MockedStatic<Mac> macStatic = mockStatic(Mac.class)) {
+            macStatic.when(() -> Mac.getInstance(anyString())).thenReturn(mockMac);
+
+            SecretKey key = new SecretKeySpec(SECRET.getBytes(), "HmacSHA512");
+            RuntimeException ex = assertThrows(RuntimeException.class,
+                () -> DelegationTokenManager.createHmac("token-1", key));
+            assertInstanceOf(IllegalStateException.class, ex.getCause());
+        }
+    }
+
+    @Test
+    void testGetDelegationTokenReturnsCorrectHmac() {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-1");
+        DelegationToken token = manager.getDelegationToken(info);
+
+        assertNotNull(token);
+        assertEquals(info, token.tokenInfo());
+        // HMAC must be non-empty and base64-decodable
+        byte[] decoded = Base64.getDecoder().decode(token.hmacAsBase64String());
+        assertTrue(decoded.length > 0);
+    }
+
+    @Test
+    void testGetDelegationTokenHmacIsConsistent() {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-2");
+        DelegationToken token1 = manager.getDelegationToken(info);
+        DelegationToken token2 = manager.getDelegationToken(info);
+        assertArrayEquals(token1.hmac(), token2.hmac());
+    }
+
+    @Test
+    void testUpdateTokenPopulatesCache() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-3");
+        DelegationToken token = manager.getDelegationToken(info);
+
+        manager.updateToken(token);
+
+        assertNotNull(tokenCache.token("t-3"));
+        assertEquals(info, tokenCache.token("t-3"));
+    }
+
+    @Test
+    void testUpdateTokenPopulatesScramCredentials() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-4");
+        DelegationToken token = manager.getDelegationToken(info);
+
+        manager.updateToken(token);
+
+        for (String mechanism : ScramMechanism.mechanismNames()) {
+            ScramCredential cred = tokenCache.credential(mechanism, "t-4");
+            assertNotNull(cred, "Expected SCRAM credential for mechanism: " + mechanism);
+        }
+    }
+
+    @Test
+    void testUpdateTokenPopulatesHmacLookup() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-5");
+        DelegationToken token = manager.getDelegationToken(info);
+
+        manager.updateToken(token);
+
+        String lookedUpId = tokenCache.tokenIdForHmac(token.hmacAsBase64String());
+        assertEquals("t-5", lookedUpId);
+    }
+
+    @Test
+    void testRemoveTokenClearsCache() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-6");
+        DelegationToken token = manager.getDelegationToken(info);
+        manager.updateToken(token);
+
+        manager.removeToken("t-6");
+
+        assertNull(tokenCache.token("t-6"));
+    }
+
+    @Test
+    void testRemoveTokenClearsScramCredentials() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        TokenInformation info = tokenInfo("t-7");
+        DelegationToken token = manager.getDelegationToken(info);
+        manager.updateToken(token);
+
+        manager.removeToken("t-7");
+
+        for (String mechanism : ScramMechanism.mechanismNames()) {
+            assertNull(tokenCache.credential(mechanism, "t-7"),
+                "Expected SCRAM credential to be removed for mechanism: " + mechanism);
+        }
+    }
+
+    @Test
+    void testRemoveNonExistentTokenDoesNotThrow() {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        assertDoesNotThrow(() -> manager.removeToken("does-not-exist"));
+    }
+
+    @Test
+    void testGetTokensReturnsAllWhenFilterAcceptsAll() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        manager.updateToken(manager.getDelegationToken(tokenInfo("t-8")));
+        manager.updateToken(manager.getDelegationToken(tokenInfo("t-9")));
+
+        List<DelegationToken> tokens = manager.getTokens(ti -> true);
+        assertEquals(2, tokens.size());
+    }
+
+    @Test
+    void testGetTokensReturnsNoneWhenFilterRejectsAll() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        manager.updateToken(manager.getDelegationToken(tokenInfo("t-10")));
+
+        List<DelegationToken> tokens = manager.getTokens(ti -> false);
+        assertTrue(tokens.isEmpty());
+    }
+
+    @Test
+    void testGetTokensFiltersCorrectly() throws NoSuchAlgorithmException {
+        DelegationTokenManager manager = managerWithSecret(SECRET);
+        manager.updateToken(manager.getDelegationToken(tokenInfo("t-11")));
+        manager.updateToken(manager.getDelegationToken(tokenInfo("t-12")));
+
+        List<DelegationToken> tokens = manager.getTokens(ti -> "t-11".equals(ti.tokenId()));
+        assertEquals(1, tokens.size());
+        assertEquals("t-11", tokens.get(0).tokenInfo().tokenId());
+    }
+
+    @Test
+    void testFilterTokenOwnerCanSeeOwnToken() {
+        TokenInformation info = tokenInfo("t-13");
+        boolean result = DelegationTokenManager.filterToken(
+            OWNER, Optional.empty(), info, id -> false, p -> false);
+        assertTrue(result);
+    }
+
+    @Test
+    void testFilterTokenRenewerCanSeeToken() {
+        TokenInformation info = tokenInfo("t-14");
+        boolean result = DelegationTokenManager.filterToken(
+            RENEWER, Optional.empty(), info, id -> false, p -> false);
+        assertTrue(result);
+    }
+
+    @Test
+    void testFilterTokenStrangerCannotSeeTokenWithoutAuthorization() {
+        TokenInformation info = tokenInfo("t-15");
+        boolean result = DelegationTokenManager.filterToken(
+            STRANGER, Optional.empty(), info, id -> false, p -> false);
+        assertFalse(result);
+    }
+
+    @Test
+    void testFilterTokenStrangerCanSeeTokenWhenAuthorizedByTokenId() {
+        TokenInformation info = tokenInfo("t-16");
+        boolean result = DelegationTokenManager.filterToken(
+            STRANGER, Optional.empty(), info, id -> true, p -> false);
+        assertTrue(result);
+    }
+
+    @Test
+    void testFilterTokenStrangerCanSeeTokenWhenAuthorizedByOwner() {
+        TokenInformation info = tokenInfo("t-17");
+        boolean result = DelegationTokenManager.filterToken(
+            STRANGER, Optional.empty(), info, id -> false, p -> true);
+        assertTrue(result);
+    }
+
+    @Test
+    void testFilterTokenExcludedWhenNotInRequestedOwners() {
+        TokenInformation info = tokenInfo("t-18");
+        // Request only tokens owned by STRANGER — but the token is owned by OWNER
+        boolean result = DelegationTokenManager.filterToken(
+            OWNER, Optional.of(List.of(STRANGER)), info, id -> true, p -> true);
+        assertFalse(result);
+    }
+
+    @Test
+    void testFilterTokenIncludedWhenInRequestedOwners() {
+        TokenInformation info = tokenInfo("t-19");
+        boolean result = DelegationTokenManager.filterToken(
+            OWNER, Optional.of(List.of(OWNER)), info, id -> false, p -> false);
+        assertTrue(result);
+    }
+
+    @Test
+    void testFilterTokenEmptyOwnersListExcludesAll() {
+        TokenInformation info = tokenInfo("t-20");
+        // Empty list means "no requested owners" → should exclude the token
+        boolean result = DelegationTokenManager.filterToken(
+            OWNER, Optional.of(List.of()), info, id -> true, p -> true);
+        assertFalse(result);
+    }
+}
